<template><article class="operations-page" aria-labelledby="ops-title"><p class="sr-only" aria-live="polite">{{ controller.announcement }}</p><header><h1 id="ops-title">运营看板</h1><p>全面掌握数智展厅运营核心指标与运行状态，助力数据化运营与持续优化</p><div class="period" role="group" aria-label="统计周期"><button v-for="item in periods" :key="item[0]" type="button" :aria-pressed="controller.period===item[0]" @click="controller.setPeriod(item[0])">{{ item[1] }}</button><label>开始日期<input type="date" :value="controller.range.start" @change="controller.setRange('start',$event.target.value)" /></label><span aria-hidden="true">至</span><label>结束日期<input type="date" :value="controller.range.end" @change="controller.setRange('end',$event.target.value)" /></label><button type="button" disabled title="本地演示不生成导出文件">导出数据</button></div></header><section class="ops-stats"><article v-for="(stat,index) in controller.stats" :key="stat.label"><AppIcon :name="iconNames[index]" :size="58"/><div><small>{{ stat.label }}</small><strong>{{ stat.value }}</strong><p>较上期 ↑ {{ stat.change }}</p></div></article></section><section class="ops-grid"><article class="trend"><h2>访问趋势 <span>总访问量 {{ controller.stats[0].value }}</span></h2><div class="line" role="img" :aria-label="`访问趋势：${controller.trend.join('、')}`"><i v-for="(value,index) in controller.trend" :key="`${controller.revision}-${index}`" :style="{height:`${Math.max(18,Math.round(value/Math.max(...controller.trend)*100))}%`}"><b>{{ value }}</b></i></div></article><article class="ranking"><h2>热门应用 Top 10</h2><ol><li v-for="(app,index) in apps" :key="app"><b>{{ index+1 }}</b><span>{{ app }}</span><strong>{{ 2375-index*182 }}</strong></li></ol></article><article class="ops-notices"><h2>公告列表 <a href="/operations/announcements">查看全部</a></h2><ul><li v-for="(name,index) in notices" :key="name"><span>{{ name }}</span><b>{{ ['系统公告','数据产品部','信息管理部','数字监管部','运营管理部'][index] }}</b><time>2026-08-{{ 19-index }}</time></li></ul></article><article class="donut"><h2>用户活跃度</h2><div class="ring" role="img" aria-label="活跃用户占比 36.2%">36.2%</div><dl><div><dt>活跃用户数</dt><dd>{{ controller.stats[2].value }}</dd></div><div><dt>人均访问次数</dt><dd>6.57</dd></div><div><dt>人均使用应用数</dt><dd>3.20</dd></div></dl></article><article class="usage-chart"><h2>应用使用统计</h2><div class="line small" role="img" :aria-label="`应用使用统计：${controller.trend.join('、')}`"><i v-for="(value,index) in controller.trend" :key="index" :style="{height:`${Math.max(18,Math.round(value/Math.max(...controller.trend)*100))}%`}"></i></div></article><article class="distribution"><h2>应用类型分布</h2><div class="ring multi" role="img" aria-label="应用类型分布，共 482 个应用">482</div><ul><li v-for="(item,index) in ['AI 76 (15.8%)','EAD 42 (8.7%)','可视化驾驶舱 58 (12.0%)','可视化报表 74 (15.3%)','数据集 61 (12.7%)','指标 53 (11.0%)','海能work应用 69 (14.3%)','RPA 49 (10.2%)']" :key="item"><i :style="{background:['#7755ee','#17bd97','#f28a16','#0060a6'][index%4]}"></i>{{ item }}</li></ul></article></section><footer>数据统计区间：{{ controller.rangeLabel }}　　数据来源：数智产品展厅 <button type="button" @click="controller.refresh">刷新数据</button></footer></article></template>
